class Solution:
    def minimumPrefixRemoval(self, nums):
        i = len(nums) - 1
        while i > 0 and nums[i - 1] < nums[i]:
            i -= 1
        return i

c.cpp:
class Solution {
public:
    int minimumPrefixRemoval(vector<int>& nums) {
        int i = nums.size() - 1;
        while (i > 0 && nums[i - 1] < nums[i]) i--;
        return i;
    }
};

